import sys, json, os, time, random
import numpy as np

def read_instance(path):
    with open(path, 'r') as f:
        data = json.load(f)
    n = data['n']
    A = np.array(data['A'], dtype=np.int64)
    B = np.array(data['B'], dtype=np.int64)
    return n, A, B

def cost(perm, A, B):
    return np.sum(A * B[perm][:, perm])

def local_search(perm, A, B, start_time, budget):
    n = len(perm)
    cur_cost = cost(perm, A, B)
    while True:
        if time.time() - start_time >= budget:
            break
        i, j = random.sample(range(n), 2)
        perm[i], perm[j] = perm[j], perm[i]
        new_cost = cost(perm, A, B)
        if new_cost < cur_cost:
            cur_cost = new_cost
        else:
            perm[i], perm[j] = perm[j], perm[i]
    return perm, cur_cost

def main():
    if len(sys.argv) < 2:
        print("Usage: python solve.py <instance.json> [budget_s]")
        return
    instance_path = sys.argv[1]
    if len(sys.argv) >= 3:
        budget = float(sys.argv[2])
    else:
        budget = float(os.getenv('QAP_TIME_LIMIT_S', '10'))
    n, A, B = read_instance(instance_path)

    start_time = time.time()
    best_perm = None
    best_cost = np.inf

    while True:
        elapsed = time.time() - start_time
        if elapsed >= budget:
            break
        perm = np.arange(n)
        np.random.shuffle(perm)
        perm, cur_cost = local_search(perm.copy(), A, B, start_time, budget)
        if cur_cost < best_cost:
            best_cost = cur_cost
            best_perm = perm.copy()
        if time.time() - start_time >= budget - 0.5:
            break

    perm_1based = best_perm + 1
    print("PERMUTATION:", " ".join(map(str, perm_1based)), flush=True)

if __name__ == "__main__":
    main()
